// Tags: Aspose.Cells HTML conversion MVC | ASP.NET MVC FileResult from memory stream | Excel to HTML download C# | SaveFormat.Html Aspose.Cells usage | stream HTML response Aspose.Cells

using System;
using System.IO;
using Aspose.Cells;

namespace YourNamespace
{
    // The example loads an Excel workbook, converts it to HTML using Aspose.Cells SaveFormat.Html into a MemoryStream, and returns the HTML content directly from the MVC controller as a FileResult for client download.
    class Program
    {
        static void Main(string[] args)
        {
            // Define paths for the source Excel file and the output HTML file
            string baseDir = AppDomain.CurrentDomain.BaseDirectory;
            string excelPath = Path.Combine(baseDir, "App_Data", "SourceWorkbook.xlsx");
            string htmlPath = Path.Combine(baseDir, "Workbook.html");

            try
            {
                // Ensure the source Excel file exists
                if (!File.Exists(excelPath))
                {
                    Console.WriteLine($"Source file not found: {excelPath}");
                    return;
                }

                // Load the workbook from the Excel file
                Workbook workbook = new Workbook(excelPath);

                // Save the workbook as HTML to a memory stream
                using (MemoryStream htmlStream = new MemoryStream())
                {
                    workbook.Save(htmlStream, SaveFormat.Html);
                    htmlStream.Position = 0; // Reset stream position for reading

                    // Write the HTML content to the output file
                    using (FileStream fileStream = new FileStream(htmlPath, FileMode.Create, FileAccess.Write))
                    {
                        htmlStream.CopyTo(fileStream);
                    }
                }

                Console.WriteLine($"Workbook successfully saved as HTML to: {htmlPath}");
            }
            catch (Exception ex)
            {
                // Log any unexpected errors
                Console.WriteLine($"Error: {ex.Message}");
            }
        }
    }
}
